begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.pa(t text) returns uuid language sql immutable as $$select md5('programming-test-'||t)::uuid$$;
create function pg_temp.actor(t text) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.pa(t),'role','authenticated')::text,true)$$;
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) select pg_temp.pa(t),'00000000-0000-0000-0000-000000000000','authenticated','authenticated',t||'-programming@example.invalid',now(),now(),now() from unnest(array['owner','member'])t;
insert into public.organizations(id,name,slug,status) values(pg_temp.pa('org'),'Programação fictícia','programming-test','active'),(pg_temp.pa('other'),'Outro ministério fictício','programming-other','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values(pg_temp.pa('unit'),pg_temp.pa('org'),'Igreja fictícia A','a','headquarters'),(pg_temp.pa('unitb'),pg_temp.pa('org'),'Igreja fictícia B','b','campus'),(pg_temp.pa('outside'),pg_temp.pa('other'),'Externa fictícia','outside','headquarters');
insert into public.organization_memberships(id,organization_id,user_id,default_unit_id,role,status) select pg_temp.pa(t||'-m'),pg_temp.pa('org'),pg_temp.pa(t),pg_temp.pa('unit'),case when t='owner' then 'owner'::public.membership_role else 'member'::public.membership_role end,'active' from unnest(array['owner','member'])t;
create function pg_temp.cmd(a text,i uuid default null,v integer default null,d jsonb default '{}') returns jsonb language sql as $$select public.programming_admin(pg_temp.pa('org'),pg_temp.pa('unit'),a,i,v,d)$$;
create function pg_temp.first() returns timestamp language sql stable as $$select make_timestamp(extract(year from now())::integer+1,1,31,19,0,0)$$;
create function pg_temp.fields() returns jsonb language sql as $$select jsonb_build_object('title','Culto fictício de domingo','description','Somente teste local','kind','service','startsLocal',to_char(pg_temp.first(),'YYYY-MM-DD"T"HH24:MI'),'endsLocal',to_char(pg_temp.first()+interval '2 hours','YYYY-MM-DD"T"HH24:MI'),'location','Local fictício','address','','capacity',10,'category',pg_temp.pa('cat'),'cover','','repeat','monthly','count',3)$$;
create function pg_temp.ev(n integer) returns uuid language sql security definer set search_path='' as $$select id from private.church_app_events where organization_id=pg_temp.pa('org') order by starts_at,id offset n limit 1$$;
create function pg_temp.detail(n integer) returns jsonb language sql as $$select pg_temp.cmd('detail',pg_temp.ev(n))$$;
select pg_temp.actor('member');
set local role authenticated;
select throws_ok($$select pg_temp.cmd('list')$$,'42501','member_agenda_denied','membro não acessa gestão');
reset role;
select pg_temp.actor('owner');
set local role authenticated;
select lives_ok($$select pg_temp.cmd('category',pg_temp.pa('cat'),0,'{"name":"Cultos","color":"#285c45","active":true}')$$,'categoria da igreja criada');
select lives_ok($$select pg_temp.cmd('create',pg_temp.pa('request'),null,pg_temp.fields())$$,'série mensal cria rascunhos');
select is(pg_temp.cmd('list')->>'total','3','três ocorrências independentes');
select is(pg_temp.cmd('list',null,null,'{"size":"2","page":"2"}')->'items'->0->>'title','Culto fictício de domingo','paginação do servidor');
select is((pg_temp.cmd('list',null,null,'{"size":"2","page":"2"}')->'items'->0->>'starts_at')::timestamptz,(pg_temp.first()+interval '2 months') at time zone 'America/Sao_Paulo','recorrência mensal ancorada no dia original');
select is(substring(pg_temp.detail(1)->'event'->>'starts_at',1,10),to_char(pg_temp.first()+interval '1 month','YYYY-MM-DD'),'mês curto usa último dia');
select lives_ok($$select pg_temp.cmd('create',pg_temp.pa('request'),null,pg_temp.fields())$$,'tentativa repetida retorna recibo');
select is(pg_temp.cmd('list')->>'total','3','repetição não duplica encontros');
select throws_ok($$select pg_temp.cmd('create',pg_temp.pa('request'),null,pg_temp.fields()||'{"count":4}')$$,'40001','member_event_changed','mesma tentativa com conteúdo diferente recusada');
select throws_ok($$select pg_temp.cmd('create',pg_temp.pa('bad'),null,pg_temp.fields()||'{"count":53}')$$,'22023','invalid_member_agenda','série limitada');
select is(pg_temp.cmd('calendar',null,null,jsonb_build_object('from',to_char(pg_temp.first(),'YYYY-MM-DD'),'to',to_char(pg_temp.first()+interval '1 month 1 day','YYYY-MM-DD')))->'days'->>to_char(pg_temp.first()+interval '1 month','YYYY-MM-DD'),'1','contagem mensal não depende da página');
select throws_ok($$select pg_temp.cmd('calendar',null,null,'{"from":"2027-01-01","to":"2028-01-01"}')$$,'22023','invalid_member_agenda','intervalo de calendário limitado');
select lives_ok($$select pg_temp.cmd('edit',pg_temp.ev(0),1,(pg_temp.fields()-array['repeat','count'])||jsonb_build_object('future',false,'versions','{}'::jsonb,'title','Exceção fictícia'))$$,'edição somente da ocorrência');
select is(pg_temp.detail(1)->'event'->>'title','Culto fictício de domingo','outras ocorrências preservadas');
select throws_ok($$select pg_temp.cmd('edit',pg_temp.ev(0),2,(pg_temp.fields()-array['repeat','count'])||jsonb_build_object('future',true,'versions',jsonb_build_object(pg_temp.ev(0),2)))$$,'40001','member_event_changed','conjunto incompleto da série recusado');
select lives_ok($$select pg_temp.cmd('edit',pg_temp.ev(0),2,(pg_temp.fields()-array['repeat','count'])||jsonb_build_object('future',true,'versions',pg_temp.detail(0)->'versions','title','Série atualizada','startsLocal',to_char(pg_temp.first()+interval '1 hour','YYYY-MM-DD"T"HH24:MI'),'endsLocal',to_char(pg_temp.first()+interval '3 hours','YYYY-MM-DD"T"HH24:MI')))$$,'edição futura atômica');
select is((pg_temp.detail(1)->'event'->>'starts_at')::timestamptz,(pg_temp.first()+interval '1 month 1 hour') at time zone 'America/Sao_Paulo','diferença de horário aplicada ao futuro');
select lives_ok($$select pg_temp.cmd('publish',pg_temp.ev(0),3,jsonb_build_object('future',true,'versions',pg_temp.detail(0)->'versions'))$$,'publica série após confirmação');
select is(pg_temp.cmd('list',null,null,'{"status":"published"}')->>'total','3','todas publicadas');
select throws_ok($$select pg_temp.cmd('cancel',pg_temp.ev(0),3,jsonb_build_object('future',false,'versions','{}'::jsonb))$$,'40001','member_event_changed','revisão antiga recusada');
select lives_ok($$select pg_temp.cmd('cancel',pg_temp.ev(0),4,jsonb_build_object('future',false,'versions','{}'::jsonb))$$,'cancelamento isolado');
select is(pg_temp.cmd('list',null,null,'{"status":"cancelled"}')->>'total','1','apenas ocorrência selecionada cancelada');
select lives_ok($$select pg_temp.cmd('category',pg_temp.pa('cat'),1,'{"name":"Cultos","color":"#285c45","active":false}')$$,'categoria arquivada');
select throws_ok($$select pg_temp.cmd('create',pg_temp.pa('inactive'),null,pg_temp.fields())$$,'22023','invalid_member_agenda','categoria arquivada não aceita novos eventos');
select throws_ok($$select public.programming_admin(pg_temp.pa('other'),pg_temp.pa('outside'),'detail',pg_temp.ev(1))$$,'42501','community_denied','ministério externo recusado');
select throws_ok($$select public.programming_admin(pg_temp.pa('org'),pg_temp.pa('unitb'),'detail',pg_temp.ev(1))$$,'42501','member_agenda_denied','evento de outra unidade não aparece');
select is(pg_temp.cmd('list',null,null,'{"search":"inexistente"}')->>'total','0','busca real no banco');
select throws_ok($$select count(*) from private.programming_categories$$,'42501',null,'sem leitura direta de categorias');
reset role;
select ok(not has_table_privilege('anon','private.programming_requests','select'),'recibos privados');
select ok(not has_function_privilege('anon','public.programming_admin(uuid,uuid,text,uuid,integer,jsonb)','execute'),'anônimo não executa RPC');
select ok(exists(select 1 from public.audit_logs where organization_id=pg_temp.pa('org') and action='programming.category.save'),'categorias auditadas');
set local role authenticated;
select lives_ok($$select pg_temp.cmd('create',pg_temp.pa('free'),null,pg_temp.fields()||jsonb_build_object('category','','repeat','none','count',1,'startsLocal',to_char(pg_temp.first()+interval '3 months','YYYY-MM-DD"T"HH24:MI'),'endsLocal',to_char(pg_temp.first()+interval '3 months 2 hours','YYYY-MM-DD"T"HH24:MI')))$$,'novo evento isolado');
select lives_ok($$select pg_temp.cmd('price',pg_temp.ev(3),1,'{"amount":"0","purpose":""}')$$,'preço gratuito configurado no próprio evento');
select throws_ok($$select pg_temp.cmd('publish',pg_temp.ev(3),1,'{"future":false,"versions":{}}')$$,'40001','member_event_changed','preço atualizado invalida publicação de detalhe antigo');
select lives_ok($$select public.member_event_purchase(pg_temp.pa('org'),pg_temp.pa('unit'),'price',pg_temp.ev(3),'{"amount":"0","purpose":""}')$$,'cliente anterior mantém configuração de preço');
select throws_ok($$select pg_temp.cmd('publish',pg_temp.ev(3),2,'{"future":false,"versions":{}}')$$,'40001','member_event_changed','alteração por cliente anterior também invalida detalhe antigo');
reset role;
insert into private.church_app_events(organization_id,unit_id,title,kind,starts_at,ends_at,capacity) select pg_temp.pa('org'),pg_temp.pa('unit'),'Volume fictício '||n,'event',now()+interval '10 days'+n*interval '1 hour',now()+interval '10 days'+(n+1)*interval '1 hour',20 from generate_series(1,107)n;
set local role authenticated;
select is(pg_temp.cmd('list')->>'total','111','listagem inclui eventos além do limite antigo de cem');
select is(jsonb_array_length(pg_temp.cmd('list',null,null,'{"size":"20","page":"6"}')->'items'),11,'última página completa acima de cem registros');
reset role;
select * from finish();
rollback;
